from pathlib import Path

# Parse the challenge.py file for K1-K6 definitions
def extract_key_bytes():
    import re
    d = {}
    src = Path('challenge.py').read_text()
    for k in ['K1','K2','K3','K4','K5','K6']:
        # Find the line defining this key
        m = re.search(rf"{k}\s*=\s*b(["'])([^\1]+?)\1", src)
        if not m:
            continue
        raw = m.group(2)
        # Convert python-like bytes string to real bytes
        val = eval(f"b'{raw}'")
        d[k] = val
    return d

if __name__ == '__main__':
    keys = extract_key_bytes()
    for k, v in keys.items():
        print(f"{k}: {len(v)} bytes")

